CREATE TEMPORARY VIEW search_base_${grass_region_without_quote} AS
SELECT  user_id
       ,device_id
       ,platform
       ,session_id
       ,keyword as query
       ,search_session_id
       ,sort_type
       ,request_id
       ,shop_id
       ,item_id
       ,is_ads
       ,location
       ,name as item_name
       ,images as item_images
       ,rule_ids as queues
       ,rel_add
       ,rel_lx
       ,rel_raw
       ,max(imp_time) as imp_time
       ,max(case when clk_time is not null then 1 else 0 end) as is_click
       ,max(case when atc_time is not null then 1 else 0 end) as is_atc
       ,max(case when order_create_time is not null then 1 else 0 end) as is_order
FROM srdi_mart.dwd_fp_search_base_1d
WHERE country IN (${grass_region}) AND dt = ${local_date}
group by country, dt, user_id, device_id, platform, session_id, keyword, search_session_id,
          sort_type, request_id, shop_id, item_id, is_ads, location, name, images, rule_ids,
          rel_add, rel_lx, rel_raw
having max(imp_time)>0;

--sql_divide_splitter--

CREATE TEMPORARY VIEW reg_domain_${grass_region_without_quote} AS
SELECT region_domain
from search_data.dim_tmp_region_domain_map
where region IN (${grass_region});

--sql_divide_splitter--

SET region_domain_${grass_region_without_quote} = (
    SELECT max(region_domain)
    from search_data.dim_tmp_region_domain_map
    where region IN (${grass_region})
)

--sql_divide_splitter--

CREATE TEMPORARY VIEW dim_item_${grass_region_without_quote} AS
SELECT item_id
      ,item_sold_cnt
      ,item_rating_score
      ,price
FROM srdi_mart.dim_sr_data_warehouse_item
WHERE grass_region IN (${grass_region}) AND local_date = ${local_date} and item_status = 1;

--sql_divide_splitter--

CREATE TEMPORARY VIEW user_activeness_${grass_region_without_quote} AS
SELECT DISTINCT user_id, search_activeness_type
FROM srdi_mart.dws_sr_data_warehouse_user_activeness_1d
WHERE grass_region IN (${grass_region}) AND local_date = ${local_date};

--sql_divide_splitter--

CREATE TEMPORARY VIEW search_base_merged_${grass_region_without_quote} AS
SELECT a.user_id
      ,a.device_id
      ,a.platform
      ,a.session_id
      ,a.query
      ,a.search_session_id
      ,a.sort_type
      ,a.request_id
      ,a.shop_id
      ,a.item_id
      ,a.is_ads
      ,a.location
      ,a.item_name
      ,a.item_images
      ,a.queues
      ,a.rel_add
      ,a.rel_lx
      ,a.rel_raw
      ,a.imp_time
      ,a.is_click
      ,a.is_atc
      ,a.is_order
      ,${region_domain_${grass_region_without_quote}} as region_domain
      ,b.price
      ,b.item_sold_cnt
      ,b.item_rating_score
      ,c.search_activeness_type
FROM search_base_${grass_region_without_quote} a
LEFT JOIN dim_item_${grass_region_without_quote} b
ON a.item_id = b.item_id
LEFT JOIN user_activeness_${grass_region_without_quote} c
ON a.user_id = c.user_id

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dwd_sr_data_warehouse_search_session_level_metrics
PARTITION (
     grass_region = ${grass_region}
    ,local_date = ${local_date}
)
SELECT
       user_id
      ,session_id
      ,search_session_id
      ,request_id
      ,query
      ,item_id
      ,location
      ,is_ads
      ,timestamp_timezone_convert(imp_time, ${grass_region}, 'yyyy-MM-dd HH:mm:ss') as imp_datetime
      ,split(item_images, ',') as item_images
      ,CONCAT('https://cf.', region_domain, '/file/', split(item_images, ',')[0]) AS item_images_link
      ,item_name
      ,item_rating_score
      ,item_sold_cnt
      ,shop_id
      ,CONCAT('https://', region_domain, '/product/', shop_id, '/', item_id) AS image_fe_link
      ,CONCAT(
               'https://admin.listing.shopee.com/product/listing/detail?itemId=',
               item_id,
               '&region=',
               ${grass_region},
               '&shopId=',
               shop_id
       ) AS image_be_link
      ,CASE WHEN is_click = 1 THEN TRUE ELSE FALSE END as is_click
      ,CASE WHEN is_atc = 1 THEN TRUE ELSE FALSE END as is_atc
      ,CASE WHEN is_order = 1 THEN TRUE ELSE FALSE END as is_order
      ,sort_type
      ,platform
      ,price
      ,queues
      ,rel_raw
      ,rel_lx
      ,rel_add
      ,search_activeness_type
from search_base_merged_${grass_region_without_quote};
